// Shared helpers for the cluster pages, stored in global context as "cps":
// API requests, HTML escaping, number formatting, tables and inline SVG charts.
// Everything rendered from API data goes through esc(), because grid and run names
// come from uploaded files.
const esc = (s) => String(s === null || s === undefined ? '' : s)
    .replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const num = (v, d = 2) => (v === null || v === undefined || Number.isNaN(Number(v)))
    ? '–' : String(Number(Number(v).toFixed(d)));

const api = (msg, method, path, body) => {
    const base = env.get('CPS_API') || 'http://127.0.0.1:8080';
    msg.method = method;
    msg.url = base + path;
    msg.headers = { 'Content-Type': 'application/json' };
    const pw = env.get('CPS_WEB_PASSWORD');
    if (pw) {
        const user = env.get('CPS_WEB_USER') || 'admin';
        msg.headers.Authorization = 'Basic ' + Buffer.from(user + ':' + pw).toString('base64');
    }
    msg.payload = body === undefined ? '' : body;
    return msg;
};

const table = (cols, rows, empty) => {
    if (!rows.length) return `<div class="cps-empty">${esc(empty || 'Nothing yet')}</div>`;
    const head = cols.map((c) => `<th${c.right ? ' class="r"' : ''}>${esc(c.label)}</th>`).join('');
    const body = rows.map((r) => '<tr>' + cols.map((c) => {
        const v = c.html ? c.html(r) : esc(c.get ? c.get(r) : r[c.key]);
        return `<td${c.right ? ' class="r"' : ''}>${v}</td>`;
    }).join('') + '</tr>').join('');
    return `<div class="cps-scroll"><table class="cps-tbl"><thead><tr>${head}</tr></thead><tbody>${body}</tbody></table></div>`;
};

const chip = (text, kind) => `<span class="cps-chip ${esc(kind)}">${esc(text)}</span>`;

// "nice" axis ticks
const ticks = (lo, hi, n) => {
    const span = hi - lo || 1;
    const step0 = span / n;
    const mag = Math.pow(10, Math.floor(Math.log10(step0)));
    const step = [1, 2, 2.5, 5, 10].map((m) => m * mag).find((s) => span / s <= n) || 10 * mag;
    const out = [];
    for (let v = Math.ceil(lo / step) * step; v <= hi + step * 1e-9; v += step) out.push(Number(v.toFixed(10)));
    return out;
};

const minmax = (arr) => {
    let lo = Infinity, hi = -Infinity;
    for (const v of arr) { if (v < lo) lo = v; if (v > hi) hi = v; }
    return [lo, hi];
};

// o: {title, xlabel, ylabel, series: [{name, color, points: [[x, y]], dash, width}],
//     band: [x0, x1], hlines: [{y, color, label}], height, bars: true}
const chart = (o) => {
    const W = 640, H = o.height || 270, L = 66, R = 14, T = 24, B = 46;
    const series = o.series.map((s) => ({ ...s, points: (s.points || []).filter((p) => p[1] !== null && p[1] !== undefined && !Number.isNaN(p[1])) }));
    const pts = series.flatMap((s) => s.points);
    if (!pts.length) return `<div class="cps-chart"><div class="cps-ctitle">${esc(o.title)}</div><div class="cps-empty">No data</div></div>`;
    let [x0, x1] = minmax(pts.map((p) => p[0]));
    if (o.xmin !== undefined) x0 = o.xmin;
    if (o.xmax !== undefined) x1 = o.xmax;
    let [y0, y1] = minmax(pts.map((p) => p[1]).concat((o.hlines || []).map((h) => h.y)));
    if (o.ymin !== undefined) y0 = Math.min(y0, o.ymin);
    if (o.bars) { const w = (x1 - x0) / Math.max(pts.length - 1, 1); x0 -= w / 2; x1 += w / 2; }
    if (x1 === x0) { x0 -= 1; x1 += 1; }
    if (y1 === y0) { y0 -= Math.abs(y0) * 0.01 || 0.5; y1 += Math.abs(y1) * 0.01 || 0.5; }
    const pad = (y1 - y0) * 0.08;
    if (o.ymin === undefined) y0 -= pad;
    y1 += pad;
    const X = (x) => L + (x - x0) / (x1 - x0) * (W - L - R);
    const Y = (y) => T + (1 - (y - y0) / (y1 - y0)) * (H - T - B);
    let g = '';
    if (o.band) {
        const a = X(Math.max(o.band[0], x0)), b = X(Math.min(o.band[1], x1));
        if (b > a) g += `<rect x="${a}" y="${T}" width="${b - a}" height="${H - T - B}" class="cps-band"/>`;
    }
    for (const v of ticks(y0, y1, 5)) {
        g += `<line x1="${L}" x2="${W - R}" y1="${Y(v)}" y2="${Y(v)}" class="cps-grid"/>` +
             `<text x="${L - 6}" y="${Y(v) + 4}" text-anchor="end" class="cps-tick">${esc(String(v))}</text>`;
    }
    for (const v of ticks(x0, x1, 6)) {
        g += `<text x="${X(v)}" y="${H - B + 19}" text-anchor="middle" class="cps-tick">${esc(String(v))}</text>`;
    }
    for (const h of o.hlines || []) {
        g += `<line x1="${L}" x2="${W - R}" y1="${Y(h.y)}" y2="${Y(h.y)}" stroke="${h.color || '#666'}" stroke-dasharray="5 4" stroke-width="1.2"/>`;
    }
    if (o.bars) {
        const n = Math.max(...series.map((s) => s.points.length));
        const bw = Math.max(1, (W - L - R) / Math.max(n, 1) * 0.8);
        for (const s of series) {
            for (const p of s.points) {
                const y = Y(Math.max(p[1], y0)), base = Y(Math.max(y0, 0));
                g += `<rect x="${X(p[0]) - bw / 2}" y="${Math.min(y, base)}" width="${bw}" height="${Math.abs(base - y)}" fill="${p[2] || s.color}"/>`;
            }
        }
    } else {
        for (const s of series) {
            if (!s.points.length) continue;
            const d = s.points.map((p, i) => `${i ? 'L' : 'M'}${X(p[0]).toFixed(1)} ${Y(p[1]).toFixed(1)}`).join('');
            g += `<path d="${d}" fill="none" stroke="${s.color}" stroke-width="${s.width || 1.8}"${s.dash ? ' stroke-dasharray="5 4"' : ''}/>`;
        }
    }
    g += `<line x1="${L}" x2="${L}" y1="${T}" y2="${H - B}" class="cps-axis"/><line x1="${L}" x2="${W - R}" y1="${H - B}" y2="${H - B}" class="cps-axis"/>`;
    if (o.xlabel) g += `<text x="${(L + W - R) / 2}" y="${H - 6}" text-anchor="middle" class="cps-lbl">${esc(o.xlabel)}</text>`;
    if (o.ylabel) g += `<text x="16" y="${(T + H - B) / 2}" text-anchor="middle" class="cps-lbl" transform="rotate(-90 16 ${(T + H - B) / 2})">${esc(o.ylabel)}</text>`;
    const legend = series.filter((s) => s.name).map((s) =>
        `<span class="cps-key"><i style="background:${s.color}"></i>${esc(s.name)}</span>`).join('') +
        (o.hlines || []).filter((h) => h.label).map((h) => `<span class="cps-key"><i class="dash" style="border-color:${h.color || '#666'}"></i>${esc(h.label)}</span>`).join('') +
        (o.band ? '<span class="cps-key"><i class="band"></i>attack window</span>' : '');
    return `<div class="cps-chart"><div class="cps-ctitle">${esc(o.title)}</div>` +
           `<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${esc(o.title)}">${g}</svg>` +
           `<div class="cps-legend">${legend}</div></div>`;
};

const kpi = (label, value, kind, hint) =>
    `<div class="cps-kpi ${kind || ''}"${hint ? ` title="${esc(hint)}"` : ''}><div class="v">${value}</div><div class="l">${esc(label)}</div></div>`;

const when = (ts) => {
    if (!ts) return '';
    const d = new Date(ts * 1000);
    return d.toLocaleString('en-GB', { hour12: false });
};

global.set('cps', { esc, num, api, table, chip, chart, kpi, when });
return null;

const cps = global.get('cps');
if (msg.statusCode !== 200) { msg.payload = `<div class="cps-err">Experiment API not reachable (${cps.esc(msg.statusCode || msg.error || '')})</div>`; return msg; }
const c = msg.payload;
const cards = c.nodes.map(n => `<div class="cps-node ${n.up ? 'up' : 'down'}">
  <div class="h"><span class="dot"></span>${cps.esc(n.host)}</div>
  <div>${n.up ? cps.esc(n.cores) + ' cores' : 'not reachable'}${n.mpi_slots ? ' · ' + cps.esc(n.mpi_slots) + ' MPI slots' : ''}</div>
  <div class="roles">${(n.roles || []).map(r => cps.chip(r === 'mpi' ? 'GridPACK MPI' : r === 'cc' ? 'control center' : r === 'ns3' ? 'NS-3' : r === 'grid' ? 'grid federate' : r === 'broker' ? 'HELICS broker' : r, 'role')).join(' ')}</div>
</div>`).join('');
msg.payload = `<div class="cps-nodes">${cards}</div>
<div class="cps-line">MPI slots in use <b>${cps.esc(c.mpi_slots_used || 0)} / ${cps.esc(c.mpi_slots)}</b> · default GridPACK ranks <b>${cps.esc(c.default_np)}</b> ·
parallel experiments <b>${cps.esc(c.max_parallel_jobs)}</b> · running <b>${cps.esc(c.running)}</b> · queued <b>${cps.esc(c.queued)}</b></div>`;
return msg;

const cps = global.get('cps');
if (msg.statusCode !== 200) return null;
const jobs = msg.payload;
// tell the user when a job finishes
const seen = flow.get('jobstate') || {};
const notes = [];
for (const j of jobs) {
  if (seen[j.id] && seen[j.id] !== j.status && (j.status === 'done' || j.status === 'failed'))
    notes.push({payload: j.status === 'done' ? `Experiment "${j.request.name}" finished` : `Experiment "${j.request.name}" failed`});
  seen[j.id] = j.status;
}
flow.set('jobstate', seen);
const kind = {queued: 'q', running: 'run', done: 'ok', failed: 'bad'};
const dur = j => j.finished ? (j.finished - j.started).toFixed(0) + ' s' : j.started ? (Date.now() / 1000 - j.started).toFixed(0) + ' s' : '';
const html = cps.table([
  {label: 'Experiment', html: j => `<b>${cps.esc(j.request.name)}</b><div class="sub">${cps.esc(j.source || 'form')} · ${cps.esc(cps.when(j.submitted))}</div>`},
  {label: 'Grid', get: j => j.grid},
  {label: 'Attack', get: j => j.request.attack},
  {label: 'MPI ranks', get: j => j.request.solver === 'gridpack' ? j.request.mpi_np : 'builtin', right: true},
  {label: 'Status', html: j => cps.chip(j.status, kind[j.status] || '') + (j.waiting ? `<div class="sub">waiting ${cps.esc(j.waiting)}</div>` : '')},
  {label: 'Time', get: dur, right: true},
  {label: 'Log', html: j => j.status === 'running' || j.status === 'failed'
      ? `<pre class="cps-log">${cps.esc((j.log_tail || '').trim().split('\n').slice(-4).join('\n'))}</pre>` : cps.esc(j.run_id || '')},
], jobs, 'No experiments yet: upload a scenario file above.');
return [{payload: html}, notes];

const cps = global.get('cps');
if (msg.statusCode !== 200) return null;
msg.payload = cps.table([
  {label: 'Grid id (use in scenario files)', html: g => `<code>${cps.esc(g.id)}</code><div class="sub">${cps.esc(g.builtin ? 'built-in' : (g.source || '') + ' · ' + (g.uploaded || ''))}</div>`},
  {label: 'Buses', get: g => g.buses, right: true},
  {label: 'Branches', get: g => g.branches, right: true},
  {label: 'Generators', get: g => g.n_gens, right: true},
  {label: 'PMUs (min)', get: g => g.pmus_min, right: true},
  {label: 'Load MW', get: g => cps.num(g.load_mw, 0), right: true},
], msg.payload, 'No grids');
return msg;

const cps = global.get('cps');
const name = (msg.file && msg.file.name) || 'grid.m';
const data = Buffer.isBuffer(msg.payload) ? msg.payload : Buffer.from(msg.payload);
return cps.api({cps: 'grid_upload'}, 'POST', '/api/grids', {filename: name, content: data.toString('base64'), encoding: 'base64'});

const cps = global.get('cps');
const name = (msg.file && msg.file.name) || 'scenario.yaml';
const data = Buffer.isBuffer(msg.payload) ? msg.payload : Buffer.from(msg.payload);
return cps.api({cps: 'scen_upload'}, 'POST', '/api/scenarios', {filename: name, content: data.toString('base64'), encoding: 'base64'});

const cps = global.get('cps');
if (msg.statusCode !== 200) {
  const d = (msg.payload && msg.payload.detail) || msg.payload;
  return [{payload: `<div class="cps-err">${cps.esc(typeof d === 'string' ? d : JSON.stringify(d))}</div>`}, {payload: 'Grid upload failed'}, null];
}
const g = msg.payload;
return [{payload: `<div class="cps-ok">Grid <code>${cps.esc(g.id)}</code> registered: ${cps.esc(g.buses)} buses, ${cps.esc(g.branches)} branches,
  ${cps.esc(g.gens.length)} generator buses, ${cps.esc(g.pmus_min)} PMUs for full observability
  (power flow converged in ${cps.esc(g.nr_iterations)} iterations). Use <code>grid: ${cps.esc(g.id)}</code> in a scenario file.</div>`},
  {payload: `Grid ${g.id} registered`}, {}];

const cps = global.get('cps');
if (msg.statusCode !== 200) {
  const d = (msg.payload && msg.payload.detail) || msg.payload;
  return [{payload: `<div class="cps-err">${cps.esc(typeof d === 'string' ? d : JSON.stringify(d))}</div>`}, {payload: 'Scenario rejected'}];
}
const jobs = msg.payload;
return [{payload: `<div class="cps-ok">Queued ${jobs.length} experiment${jobs.length > 1 ? 's' : ''}: ${jobs.map(j => '<b>' + cps.esc(j.request.name) + '</b> on ' + cps.esc(j.grid) + (j.request.solver === 'gridpack' ? ' (' + cps.esc(j.request.mpi_np) + ' MPI ranks)' : '')).join(', ')}.</div>`},
  {payload: `Queued ${jobs.length} experiment(s)`}];

msg.headers = {'Content-Type': 'text/yaml; charset=utf-8', 'Content-Disposition': 'attachment; filename="scenario.yaml"'};
if (typeof msg.payload !== 'string') msg.payload = String(msg.payload);
msg.statusCode = 200;
return msg;

if (msg.statusCode !== 200) return null;
const runs = msg.payload;
const sig = runs.map(r => r.id).join(',');
let sel = flow.get('run');
const out = [null, null];
// open the newest run when nothing is selected yet, or when a new run has finished
const newest = runs.length ? runs[0].id : null;
const prev = flow.get('newest');
flow.set('newest', newest);
if (newest && (!sel || (prev && prev !== newest))) { sel = newest; out[1] = {payload: newest}; }
if (sig !== flow.get('runsig') || out[1]) {
  flow.set('runsig', sig);
  out[0] = {payload: runs, selected: sel};
}
return out;

const cps = global.get('cps');
const id = msg.payload;
flow.set('run', id);
flow.set('bus', null);
return [[cps.api({cps: 'run'}, 'GET', '/api/runs/' + encodeURIComponent(id)),
         cps.api({cps: 'series'}, 'GET', '/api/runs/' + encodeURIComponent(id) + '/series')]];

const cps = global.get('cps');
const id = flow.get('run'); const bus = parseInt(msg.payload, 10);
if (!id || !bus) return null;
flow.set('bus', bus);
return cps.api({cps: 'series'}, 'GET', '/api/runs/' + encodeURIComponent(id) + '/series?bus=' + bus);

const cps = global.get('cps');
if (msg.statusCode !== 200) return null;
const r = msg.payload, s = r.summary, a = r.meta.args, net = s.network, cc = s.control_center, g = s.grid, at = s.attack;
const gp = s.gridpack || {}, cl = s.cluster || r.meta.cluster || {};
const pct = v => v == null ? '–' : cps.num(v, 1) + '%';
const k = [];
k.push(cps.kpi('Frames delivered', pct(100 * net.delivery_ratio), net.delivery_ratio > 0.98 ? 'good' : net.delivery_ratio > 0.9 ? 'warn' : 'bad'));
k.push(cps.kpi('Latency p95', cps.num(net.latency_ms.p95, 1) + ' ms', ''));
k.push(cps.kpi('Complete PDC sets', pct(cc.complete_sets_pct), cc.complete_sets_pct > 95 ? 'good' : cc.complete_sets_pct > 70 ? 'warn' : 'bad'));
